impl Solution {
    pub fn top_k_frequent(nums: Vec<i32>, k: i32) -> Vec<i32> {
        let mut counts = HashMap::new();
        for num in nums {
            *counts.entry(num).or_insert(0) += 1;
        }

        let mut unique: Vec<i32> = counts.keys().cloned().collect();
        unique.sort_unstable_by(|a, b| counts[b].cmp(&counts[a]));

        unique.into_iter().take(k as usize).collect()
    }
}

